 if(stage==3){expectTime(now,"Cyclic emerald delivery timeout");if(GolemClient.count(out,Items.GOLD_INGOT)!=6||GolemClient.count(out,Items.EMERALD)!=3)return;check(GolemClient.count(in,Items.GOLD_INGOT)==1&&GolemClient.count(in,Items.EMERALD)==1&&g.cargo.getItem(0).is(Items.EMERALD)&&g.cargo.getItem(0).getCount()==3,"Cyclic cursor skipped filter or surplus lost");stage=4;due=now+6000;Thaumcraft.LOGGER.info("FINISH_EMERALD_READY: cyclic ninth sample moved six emeralds, three delivered/three retained; ready to select ninth sample and raise quota");return;}
 if(stage==4){expectTime(now,"Final quota timeout");if(GolemClient.count(out,Items.EMERALD)!=6||!g.cargo.isEmpty())return;stage=5;due=now+60;return;}
