 if(stage==7){expectTime(now,"Factory stock timeout");var top=(ChestBlockEntity)l.getBlockEntity(machine.getBlockPos().above());if(GolemClient.count(top,Items.GOLD_NUGGET)!=18)return;check(GolemClient.count(in,Items.GOLD_NUGGET)==1&&g.cargo.isEmpty()&&machine.crafts()==0,"Provider leave-one or factory redstone failed");l.removeBlock(machine.getBlockPos().south(),false);stage=8;due=now+300;Thaumcraft.LOGGER.info("FINISH_FACTORY_INPUT_OK: eighteen paid nuggets delivered, one retained, powered factory still idle");return;}
 if(stage==8){expectTime(now,"Pattern factory timeout");if(machine.crafts()!=2)return;check(GolemClient.count(out,Items.GOLD_INGOT)==2&&((ChestBlockEntity)l.getBlockEntity(machine.getBlockPos().above())).isEmpty()&&GolemClient.count(in,Items.GOLD_NUGGET)==1&&g.cargo.isEmpty(),"Factory conservation failed");clear();g.discard();
 source=LogisticsClient.chestSeal(p,SealKind.PROVIDER,Q.west(7));in=(ChestBlockEntity)l.getBlockEntity(source.support());in.setItem(0,new ItemStack(Items.WHEAT_SEEDS,3));dest=GolemProbe.seal(p,SealKind.HARVEST,Q.west(3));edit(p,dest,32);var crop=Q.west(4);l.setBlockAndUpdate(crop.below(),Blocks.FARMLAND.defaultBlockState());dest.replants.put(crop,Blocks.WHEAT.defaultBlockState());dest.setChanged();g=worker(p,new GolemDesign(3,1,1,3),Q.west(2));stage=9;due=now+600;Thaumcraft.LOGGER.info("FINISH_FACTORY_OK: provider → flying hauler → stock → two paid pattern crafts; nineteen nuggets become two ingots plus one nugget");return;}
 if(stage==9){expectTime(now,"Seed provisioning timeout");if(!l.getBlockState(Q.west(4)).is(Blocks.WHEAT))return;check(dest.replants.isEmpty()&&GolemClient.count(in,Items.WHEAT_SEEDS)==2&&g.cargo.isEmpty(),"Replant did not pay physical seed");l.setBlockAndUpdate(Q.west(4),((CropBlock)Blocks.WHEAT).getStateForAge(7));stage=10;due=now+300;Thaumcraft.LOGGER.info("FINISH_SEED_OK: queued replant fetched one physical seed and placed native crop");return;}
 if(stage==10){expectTime(now,"Paid replant harvest timeout");var state=l.getBlockState(Q.west(4));if(!state.is(Blocks.WHEAT)||state.getValue(CropBlock.AGE)!=0)return;check(GolemClient.count(in,Items.WHEAT_SEEDS)==2&&!g.cargo.isEmpty(),"Harvest stole provider seed or lost loot");g.dropCargo(l);open(p,dest);stage=11;Thaumcraft.LOGGER.info("FINISH_REPLANT_READY: mature wheat replanted using real harvested seed; ready for native Replant toggle");return;}
 if(stage==11&&!dest.replant){l.setBlockAndUpdate(Q.west(4),((CropBlock)Blocks.WHEAT).getStateForAge(7));stage=12;due=now+300;return;}
 if(stage==12){expectTime(now,"Replant-off harvest timeout");if(!l.isEmptyBlock(Q.west(4)))return;check(dest.replants.isEmpty()&&!g.cargo.isEmpty(),"Replant-off queued/free planted crop");p.closeContainer();clear();g.dropCargo(l);g.discard();
 source=GolemProbe.seal(p,SealKind.HARVEST,Q.west(3));var cane=Q.offset(-4,0,-2);l.setBlockAndUpdate(cane.below(),Blocks.DIRT.defaultBlockState());l.setBlockAndUpdate(cane.below().north(),Blocks.WATER.defaultBlockState());l.setBlockAndUpdate(cane,Blocks.SUGAR_CANE.defaultBlockState());l.setBlockAndUpdate(cane.above(),Blocks.SUGAR_CANE.defaultBlockState());g=worker(p,new GolemDesign(3,1,1,3),Q.west(2));stage=13;due=now+300;Thaumcraft.LOGGER.info("FINISH_REPLANT_OFF_OK: native toggle harvested without consuming seed or creating replant task");return;}
 if(stage==13){expectTime(now,"Tall crop harvest timeout");var cane=Q.offset(-4,0,-2);if(!l.isEmptyBlock(cane.above()))return;check(l.getBlockState(cane).is(Blocks.SUGAR_CANE)&&g.cargo.getItem(0).is(Items.SUGAR_CANE),"Tall crop base destroyed or loot missing: base="+l.getBlockState(cane)+" cargo="+g.cargo.getItem(0));clear();g.dropCargo(l);g.discard();g=worker(p,new GolemDesign(1,1,2,0),Q.west(2));victim=BatRiftClient.mob(p,Vec3.atBottomCenterOf(Q.west()));p.setInvulnerableTime(0);check(p.hurtServer(l,l.damageSources().mobAttack(victim),1),"Owner defense setup failed");stage=14;defenseHit=now;due=now+300;Thaumcraft.LOGGER.info("FINISH_CROPS_OK: paid/no-replant wheat and native tall sugar cane with base retained");return;}
